import http from 'http';
import fs from 'fs';
import path from 'path';
import { serve } from '../src/serve';

function createTempDir(prefix: string): string {
  const dir = path.resolve(__dirname, '..', `${prefix}-${Date.now()}`);
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

function cleanupDir(dir: string): void {
  if (fs.existsSync(dir)) fs.rmSync(dir, { recursive: true, force: true });
}

function get(url: string, port: number, host: string = 'localhost'): Promise<{ status: number; body: string; headers: http.IncomingHttpHeaders }> {
  return new Promise((resolve, reject) => {
    http.get(`http://${host}:${port}${url}`, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          status: res.statusCode || 0,
          body: Buffer.concat(chunks).toString(),
          headers: res.headers,
        });
      });
    }).on('error', reject);
  });
}

describe('serve', () => {
  let tempContent: string;
  let tempOutput: string;
  let tempTemplates: string;
  let port: number;
  const usedServers: http.Server[] = [];

  function createFixture(): { server: http.Server; port: number } {
    tempContent = createTempDir('serve-content');
    tempOutput = createTempDir('serve-output');
    tempTemplates = createTempDir('serve-templates');

    fs.mkdirSync(path.join(tempTemplates, 'layouts'), { recursive: true });
    fs.mkdirSync(path.join(tempTemplates, 'partials'), { recursive: true });

    fs.writeFileSync(
      path.join(tempTemplates, 'layouts', 'default.hbs'),
      '<!DOCTYPE html><html><head><title>{{title}}</title></head><body>{{{body}}}</body></html>'
    );
    fs.writeFileSync(
      path.join(tempTemplates, 'index.hbs'),
      '<h1>My Site</h1><ul>{{#each pages}}<li><a href="{{slug}}.html">{{title}}</a></li>{{/each}}</ul>'
    );
    fs.writeFileSync(
      path.join(tempTemplates, 'page.hbs'),
      '<article><h1>{{title}}</h1><div>{{{content}}}</div></article>'
    );

    fs.writeFileSync(
      path.join(tempContent, 'hello.md'),
      `---\ntitle: Hello World\ndate: 2025-01-01\n---\n# Hello`
    );
    fs.writeFileSync(
      path.join(tempContent, 'about.md'),
      `---\ntitle: About\n---\n## About Us`
    );

    port = 1024 + Math.floor(Math.random() * 50000);

    const server = serve({
      contentDir: tempContent,
      outputDir: tempOutput,
      templatesDir: tempTemplates,
      port,
    });

    usedServers.push(server);
    return { server, port };
  }

  afterEach(() => {
    for (const s of usedServers.splice(0)) {
      s.close();
      s.closeAllConnections?.();
    }
    cleanupDir(tempContent || '');
    cleanupDir(tempOutput || '');
    cleanupDir(tempTemplates || '');
  });

  test('serves index.html at /', async () => {
    const { port } = createFixture();
    const res = await get('/', port);
    expect(res.status).toBe(200);
    expect(res.body).toContain('<h1>My Site</h1>');
    expect(res.body).toContain('Hello World');
    expect(res.body).toContain('About');
  });

  test('serves individual page html', async () => {
    const { port } = createFixture();
    const res = await get('/hello.html', port);
