function closeServer(srv: http.Server): Promise<void> {
  return new Promise((resolve) => {
    const timeout = setTimeout(() => resolve(), 2000);
    srv.closeAllConnections?.();
    srv.close(() => {
      clearTimeout(timeout);
      resolve();
    });
  });
}

